<template>
  <div class="page boxing-page boxing-page-{{ screenSize }} boxing-page-{{ screenViewport }}">
    <div class="boxing-topline">
      <text class="boxing-session">节奏拳</text>
      <text class="boxing-remaining">{{ boxingRemainingText }}</text>
    </div>

    <div class="boxing-stats boxing-stats-{{ screenViewport }}">
      <div class="boxing-stat">
        <text class="boxing-stat-label">得分</text>
        <text class="boxing-stat-value">{{ boxingScoreText }}</text>
      </div>
      <div class="boxing-stat">
        <text class="boxing-stat-label">连击</text>
        <text class="boxing-stat-value boxing-streak-value {{ boxingComboClass }}">{{ boxingStreakText }}</text>
      </div>
    </div>

    <div class="fighter-stage fighter-stage-{{ screenSize }} fighter-stage-{{ screenViewport }} {{ boxingTargetClass }}" onclick="simulatePunch">
      <div class="impact-wave impact-wave-{{ screenViewport }} impact-wave-one {{ boxingTargetClass }}-wave"></div>
      <div class="impact-wave impact-wave-{{ screenViewport }} impact-wave-two {{ boxingTargetClass }}-wave"></div>
      <div class="fighter fighter-{{ screenViewport }} {{ boxingTargetClass }}-fighter">
        <div class="fighter-head {{ boxingTargetClass }}-head"></div>
        <div class="fighter-body {{ boxingTargetClass }}-body"></div>
        <div class="fighter-arm fighter-arm-left {{ boxingTargetClass }}-arm-left"></div>
        <div class="fighter-arm fighter-arm-right {{ boxingTargetClass }}-arm-right"></div>
        <div class="fighter-fist fighter-fist-left {{ boxingTargetClass }}-fist-left"></div>
        <div class="fighter-fist fighter-fist-right {{ boxingTargetClass }}-fist-right"></div>
        <div class="fighter-leg fighter-leg-left {{ boxingTargetClass }}-leg-left"></div>
        <div class="fighter-leg fighter-leg-right {{ boxingTargetClass }}-leg-right"></div>
      </div>
    </div>

    <text class="boxing-prompt boxing-prompt-{{ screenViewport }}">{{ boxingPrompt }}</text>
    <text class="boxing-pace">{{ boxingPaceLabel }}</text>
    <text if="{{ boxingMessage }}" class="boxing-message">{{ boxingMessage }}</text>
    <div if="{{ boxingFallback }}" class="simulate-button simulate-button-{{ screenViewport }}" onclick="simulatePunch">
      <text class="simulate-text">点击模拟出拳</text>
    </div>
    <div class="stop-button stop-button-{{ screenViewport }} boxing-stop boxing-stop-{{ screenViewport }}" onclick="stopBoxing">
      <text class="stop-text">结束训练</text>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    screenSize: { type: String, default: 'regular' },
    screenViewport: { type: String, default: 'normal' },
    boxingRemainingText: { type: String, default: '30' },
    boxingScoreText: { type: String, default: '0' },
    boxingStreakText: { type: String, default: '0' },
    boxingComboClass: { type: String, default: 'combo-calm' },
    boxingPrompt: { type: String, default: '准备' },
    boxingPaceLabel: { type: String, default: '' },
    boxingTargetClass: { type: String, default: 'target-waiting' },
    boxingFallback: { type: Boolean, default: false },
    boxingMessage: { type: String, default: '' },
  },
  simulatePunch() { this.$emit('simulatePunch'); },
  stopBoxing() { this.$emit('stopBoxing'); },
};
</script>

