 163: function keyframeSource(source, name) {
 164:   const style = source.match(/<style>([\s\S]*?)<\/style>/);
 165:   assert(style, 'component style block is required');
 166:   const marker = `@keyframes ${name}`;
 167:   const markerAt = style[1].indexOf(marker);
 168:   assert.notStrictEqual(markerAt, -1, `${name} keyframes are required`);
 169:   const openingBrace = style[1].indexOf('{', markerAt + marker.length);
 170:   let depth = 0;
 171:   for (let index = openingBrace; index < style[1].length; index += 1) {
 172:     if (style[1][index] === '{') depth += 1;
 173:     if (style[1][index] === '}') depth -= 1;
 174:     if (depth === 0) return style[1].slice(openingBrace + 1, index);
 175:   }
 176:   assert.fail(`${name} keyframes must be closed`);
 177: }
